steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams(name: \"Mobile\") {
          id
          name
          issues(filter: {
            priority: { eq: 2 },
            state: { type: { eq: BUG } }
          }) {
            id
            identifier
            title
            priority
            assignee {
              id
              name
            }
            workflowState {
              id
              name
            }
          }
        }
      }
    '
  }'
